import {
  section,
  sectionDark,
  container,
  mlAuto,
  mrAuto,
  title,
  whiteColor,
  description,
  hexToRgb
} from "assets/jss/nextjs-material-tim-andrus.js";

const examplesStyle = {
  section: {
    ...section,
    padding: "70px 0px"
  },
  sectionDark: {
    ...sectionDark,
    "& $title": {
      color: whiteColor
    },
    "& $description": {
      color: "rgba(" + hexToRgb(whiteColor) + ",0.76)"
    }
  },
  container,
  mlAuto,
  mrAuto,
  sectionDescription: {
    textAlign: "center",
    marginBottom: "90px"
  },
  title: {
    ...title,
    textAlign: "center"
  },
  description,
  imgCardExtended: {
    transition: "all .2s cubic-bezier(0.4,0,0.2,1)",
    "&:hover": {
      transform: "translate3d(0, -10px, 0)"
    }
  }
};

export default examplesStyle;
